parameters.functionCode:
// Extract text from downloaded file
const fileData = $input.item.binary.data;
const transcriptText = fileData.toString('utf-8');
const fileName = $input.item.json.filename || 'voice_note';
const filePath = $input.item.json.path;

return {
  json: {
    transcript: transcriptText,
    fileName: fileName,
    filePath: filePath,
    receivedDate: new Date().toISOString()
  }
};

// Prepare prompt for GPT-4o
const transcript = $input.item.json.transcript;

return {
  json: {
    transcript: transcript,
    fileName: $input.item.json.fileName,
    filePath: $input.item.json.filePath,
    prompt: `I have this voice note transcript from Google Recorder:\n\n"${transcript}"\n\nPlease analyze this transcript and extract individual tasks. First, call list_projects() to see what Vikunja projects are available. Then create each task in the most appropriate project based on the content. Use context clues to determine which project each task belongs to.`
  }
};

