parameters.functionCode:
// Handle GPT function calling and execute Vikunja API calls
const response = $input.item.json;
const message = response.choices[0].message;

const results = {
  functions_called: [],
  tasks_to_create: [],
  conversation_id: response.id,
  originalFileName: $input.first().json.fileName,
  originalFilePath: $input.first().json.filePath
};

// Parse function calls from GPT
if (message.tool_calls) {
  for (const toolCall of message.tool_calls) {
    const functionName = toolCall.function.name;
    const args = JSON.parse(toolCall.function.arguments);

    results.functions_called.push({
      id: toolCall.id,
      function: functionName,
      arguments: args
    });

    // Queue tasks for creation
    if (functionName === 'create_task') {
      results.tasks_to_create.push(args);
    }
  }
}

return {
  json: results
};

