parameters.functionCode:
// Collect all created tasks
const allItems = $input.all();
const tasksCreated = allItems.filter(item => item.json.id);
const fileName = $('Parse Function Calls').first().json.originalFileName;

let summary = '✅ Voice Note Processed Successfully!\n\n';
summary += `📁 File: ${fileName}\n`;
summary += `📊 Created ${tasksCreated.length} task(s):\n\n`;

for (const task of tasksCreated) {
  summary += `📌 ${task.json.title}\n`;
  if (task.json.description) {
    summary += `   ${task.json.description.substring(0, 80)}...\n`;
  }
  summary += `   🔗 https://tasks.opshub.host/tasks/${task.json.id}\n\n`;
}

summary += '\n🎉 All tasks have been added to Vikunja!\n';
summary += '\n---\n';
summary += 'Sent via Voice-to-Tasks Automation (SFTP)';

return {
  json: {
    subject: '✅ Tasks Created from Voice Note',
    body: summary,
    tasks_count: tasksCreated.length,
    file_name: fileName
  }
};
